def find_multiple():
    # Define the numbers
    num1 = 9
    num2 = 12

    # Find the prime factorization of num1 and num2
    factors_num1 = {3: 2}
    factors_num2 = {2: 2, 3: 1}

    # Determine the LCM by taking the highest power of each prime factor
    lcm_factors = {}
    for factor in set(factors_num1) | set(factors_num2):
        lcm_factors[factor] = max(factors_num1.get(factor, 0), factors_num2.get(factor, 0))

    # Calculate the LCM
    lcm = 1
    for factor, power in lcm_factors.items():
        lcm *= factor ** power

    # Check which of the given choices is a multiple of the LCM
    choices = [36, 15, 17, 5, 7]
    for choice in choices:
        if choice % lcm == 0:
            return choice

    return None

answer = find_multiple()
print(answer)

